import type { MarketEvalScenario } from "../types.ts";

function taskIntro(category: string): string {
  return `Create an evidence-grounded market map for the ${category} category.\n\n` +
    `Use the vendor ids exactly as provided. Read the supplied source URLs, choose a compact taxonomy of 4-6 specific differentiating claims, classify every vendor x claim cell as loud, quiet, absent, or unobservable, and write final artifacts. Prefer claims that separate vendors; do not add generic table-stakes claims just because one page mentions them.\n\n` +
    `Required files in the working directory:\n` +
    `1. market.config.json — fullstackgtm-compatible MarketConfig.\n` +
    `2. observations.json — fullstackgtm-compatible ObservationSet for runLabel \"run-1\".\n` +
    `3. market-report.md — a concise analyst-facing summary with fronts and caveats.\n\n` +
    `For every loud or quiet observation include at least one verbatim evidence quote copied from the source page text. Do not invent vendors, URLs, quotes, or claim ids. Failed/empty pages should be unobservable, never absent.\n\n` +
    `Use these exact JSON shapes. MarketConfig: {\"category\": string, \"anchorVendor\"?: vendorId, \"vendors\": [{\"id\": string, \"name\": string, \"urls\": {\"home\": string, \"pricing\": string|null, \"product\": string[]}, \"aliases\"?: string[]}], \"claims\": [{\"id\": string, \"capability\": string, \"icp\": string, \"pricingStructure\": string, \"definition\": string, \"terms\"?: string[]}], \"surfaceRule\"?: string}.\n\n` +
    `ObservationSet: {\"id\": string, \"category\": same category, \"runLabel\": \"run-1\", \"runAt\": ISO timestamp, \"extractor\": string, \"observations\": [{\"id\": string, \"vendorId\": vendor id, \"claimId\": claim id, \"observedAt\": YYYY-MM-DD, \"intensity\": \"loud\"|\"quiet\"|\"absent\"|\"unobservable\", \"confidence\": \"high\"|\"medium\"|\"low\", \"reason\": string, \"evidence\": [{\"id\": string, \"sourceSystem\": \"web\", \"sourceObjectType\": \"page\", \"sourceObjectId\": source URL, \"text\": verbatim quote, \"metadata\": {\"url\": source URL}}]}]}. For absent or unobservable, evidence should be [].`;
}

